import AppKit

/// The agent's six action tools — `add_action`, `add_zoom_action`,
/// `add_speed_ramp`, `set_action`, `set_action_end` and `remove_action`: the
/// action rows of
/// spec §6 (and of the op table in the module doc of `core/src/edit.rs`),
/// with the same names and the same argument names.
///
/// A pure move out of `AgentServer+Clips.swift` (issue batch B87 phase 2),
/// which stood over app/CLAUDE.md's ~600-line cap with `set_action_end`'s
/// graphic door to land. The seam is the one the file had already drawn:
/// `// MARK: - Actions` came here whole, with its bodies untouched.
extension AgentServer {

    // MARK: - Actions

    /// `add_action` — ⌥⌘K (`EditorViewController+Inspector`'s
    /// `addActionAtPlayheadCommand`) and the Clip tab's action lane's `+`; and
    /// ⌥-press on the timeline's volume line, which adds a point as an action
    /// (`VolumeLine.point`, spec §11 AU-83).
    /// `at` is CLIP time, not project time: it is measured from the clip's own
    /// start (spec §5.4).
    func addAction(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let at = try timeArg(a, "at", document)
        let duration = try optionalTimeArg(a, "duration", document)
        return try addedActionResult(
            document, clip, "Add Action",
            [.addAction(clip: clip.id, at: at, duration: duration)])
    }

    /// `add_zoom_action` — the canvas's `Z` rubber band
    /// (`ZoomRegionSession`, `EditorViewController+ZoomRegion.swift`) and the
    /// Clip tab's action lane, whose zoom-in button arms the same mode and
    /// whose zoom-out button ("Zoom Back") sends this with a null region.
    ///
    /// One op rather than `add_action` + `set_action_end` because the
    /// arithmetic that turns a rectangle into a scale and an offset belongs
    /// in the core (`core/src/edit_zoom.rs`'s module doc has the equation),
    /// and because a gesture must be one undo step.
    ///
    /// **`region` is REQUIRED here and optional in the op**, which is the one
    /// place the distinction can be made. The core's envelope reads an absent
    /// optional and an explicit null identically — the crate has no
    /// tri-state argument idiom, which `set_clip` settled in phase 2 — so a
    /// forgotten rectangle would silently become a zoom BACK, the opposite
    /// edit. Requiring the key means a caller says `null` on purpose.
    ///
    /// **The region goes to the core UNREAD** (deepening D1·5,
    /// `archive/roadmap-7.md` §2.5). It is the one op ARGUMENT that
    /// is a caller-authored object, and `edit_zoom.rs`'s `ZoomRegion` reads
    /// it the way a patch is read: an unknown member is named beside the four
    /// the region takes, a missing one is named (there is no defensible
    /// default for any of them), a wrong-typed one is named by its path, and
    /// a four-number LIST is refused rather than read positionally. The
    /// hand reader that used to do all of that member by member is gone with
    /// it.
    func addZoomAction(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let at = try timeArg(a, "at", document)
        let duration = try optionalTimeArg(a, "duration", document)
        let region = try zoomRegionArg(a, "region")
        let fit = try enumArg(a, "fit", ZoomFit.self)
        let curve = try enumArg(a, "curve", Curve.self)
        // The undo step's NAME is the one thing left that reads the region,
        // and it reads only whether it is a null: a zoom back and a zoom to
        // a rectangle are different edits to a person looking at the Edit
        // menu. What the object CONTAINS is the core's.
        return try addedActionResult(
            document, clip, region is NSNull ? "Zoom Back" : "Zoom to Region",
            [
                .addZoomActionRaw(
                    clip: clip.id, at: at, duration: duration, region: region, fit: fit,
                    curve: curve)
            ])
    }

    /// `add_speed_ramp` — Clip ▸ Speed Ramp… (`SpeedRampSheetController`,
    /// spec §11 SR-24): a speed ramp preset in one step. `from` and `to` are
    /// CLIP time, like `add_action`'s `at`.
    ///
    /// One op rather than `add_action` + `set_action_end` (SR-25), for
    /// `add_zoom_action`'s reasons: the base rate, the overlap and the rate
    /// that fits are the core's reads (D2-1), and a preset is one undo step.
    /// The undo step is named for the shape, as the sheet names it.
    func addSpeedRamp(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let shape = try requiredEnumArg(a, "shape", SpeedRampShape.self)
        guard let rate = try doubleArg(a, "rate") else {
            throw ToolError(message: "Missing required argument: rate")
        }
        let from = try optionalTimeArg(a, "from", document)
        let to = try optionalTimeArg(a, "to", document)
        let curve = try enumArg(a, "curve", Curve.self)
        let hold = try doubleArg(a, "hold")
        return try addedActionResult(
            document, clip, shape.displayName,
            [
                .addSpeedRamp(
                    clip: clip.id, shape: shape, rate: rate, from: from, to: to, curve: curve,
                    hold: hold)
            ])
    }

    /// The tail every action-adding tool shares: run the ops, then report the
    /// action the clip GAINED. Actions are not top-level ids, so
    /// `created(from:to:)` cannot see them, and the new one is the difference
    /// between the clip's action ids before and after.
    private func addedActionResult(
        _ document: ProjectDocument, _ clip: ClipSnapshot, _ actionName: String,
        _ ops: [ReelOp]
    ) throws -> String {
        let before = clip.actions.map { $0.id }
        // The landing is read BEFORE the edit, like `editResult`'s: how a call
        // was addressed is a fact about the CALL, and reading it back off a
        // view the edit could itself have moved would answer about the wrong
        // thing. It matters here for the same reason it matters there — under
        // phase 9's rule the ABSENCE of `scope` in a result means "this landed
        // on the document", so these two tools (`add_action`, `add_zoom_action`)
        // would otherwise report a nested edit as a document one.
        let landing = scopeLanding(ops, document)
        // The captions `add_speed_ramp` re-times ride in the same step
        // (spec §11 SR-27); every other action-adding tool plans nothing.
        let plan = captionRetime(ops, document)
        let snapshot = try performGroupedEdit(
            document, plan.undoName(actionName), ops + plan.ops)
        // Read back through `idScope`, not the top level: inside a scope the
        // clip that just gained an action is one of the nest's, and the
        // timeline's array has never heard of it — which would answer with an
        // empty list and report no new action at all.
        let after = try idScope(document).clip(clip.id)?.actions.map { $0.id } ?? []
        var result: [String: Any] = ["ok": true, "clip": Int(clip.id)]
        let added = after.filter { !before.contains($0) }.map { Int($0) }
        if !added.isEmpty { result["new_actions"] = added }
        result.merge(plan.answerFields) { _, new in new }
        // Empty unless the edit took a clip with sound above the ceiling,
        // which only `add_speed_ramp` of these tools can (SR-21 (e)).
        result.merge(
            SpeedAudioDrop.answerFields(from: snapshot, to: document.project.snapshot)
        ) { _, new in new }
        result.merge(landing) { _, new in new }
        result["project"] = summary(document)
        return try jsonResult(result)
    }

    /// `add_zoom_action`'s `region`, forwarded to the core UNREAD — the
    /// argument half of `rawPatchArg`, and the same one line of judgement
    /// (deepening D1·5).
    ///
    /// It reads NOTHING about the value. The core's `ZoomRegion` is the one
    /// validator of what a region may be, and it answers with the member's
    /// own path (`bad value at "region.width": invalid type: string "wide",
    /// expected f64`), where the hand reader here read the four members one
    /// at a time and had to spell what a region takes itself. An explicit
    /// `NSNull` is forwarded as it was written: the op reads a `null` as
    /// absent and both mean a zoom BACK.
    ///
    /// **The ABSENT key is the one thing left**, and unlike `rawPatchArg`'s
    /// it is not merely a mistake about the call — it is the distinction the
    /// core cannot make. An absent optional and an explicit null are one
    /// thing to the envelope, so a forgotten rectangle would be a zoom back
    /// rather than an error; the handler above says why the tool draws a
    /// line the op does not.
    private func zoomRegionArg(_ a: [String: Any], _ key: String) throws -> Any {
        guard let raw = a[key] else {
            throw ToolError(
                message: "Missing required argument: \(key) — the rectangle to zoom to, as "
                    + "{x, y, width, height} in SOURCE pixels, where x and y are its CENTRE "
                    + "measured from the centre of the clip's cropped rect. Pass null to zoom "
                    + "BACK to the clip's own scale and position.")
        }
        return raw
    }

    /// `set_action` — the Clip tab's action lane: the selected action's
    /// Start, Length and Curve in its detail row, and dragging a band's body
    /// (move) or its outer 5 pt (resize) in that lane or on the timeline's
    /// action lane (spec §11 CI-11); and ⌥-press on the volume line inside a
    /// volume action, which shortens it and re-curves the new half
    /// (`VolumeLine.point`, spec §11 AU-83). An action running past its clip's end
    /// can be re-curved there (the detail row's Curve popup), moved earlier
    /// or shortened, never taken further out (spec §11 SR-22, #338).
    func setAction(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let action = try actionArg(a, "action", clip)
        let start = try optionalTimeArg(a, "start", document)
        let duration = try optionalTimeArg(a, "duration", document)
        let curve = try enumArg(a, "curve", Curve.self)
        guard start != nil || duration != nil || curve != nil else {
            throw ToolError(message: "set_action needs start, duration or curve.")
        }
        return try retimingEditResult(
            document, "Action",
            [
                .setAction(
                    clip: clip.id, action: action.id, start: start, duration: duration,
                    curve: curve)
            ])
    }

    /// `set_action_end` — every inspector field written with an action
    /// SELECTED (spec §11 CI-2, `InspectorBinding.ops(video:for:)`). The patch
    /// is the action's END state, merged; a key set to null is REMOVED from
    /// it — the UI path of a null is a section header's Clear, a keyed row's
    /// × and its menu's "Remove from action N" (`InspectorBinding.clearOps`,
    /// spec §11 CI-9). A patch naming `speed` is the Clip tab's Speed section's
    /// Rate with the action selected (`VideoPane.rateOps`, spec §11 SR-21 (a)).
    /// A patch naming only `audio.volume` is also a drag on the timeline's
    /// volume line where an action's end is in force, and its ⌥-press's new
    /// point (`VolumeLineSession`, spec §11 AU-82, AU-83). A patch naming
    /// `audio` is also the Sound tab's Mix, Channels, EQ, Hum, Noise
    /// Reduction, Gate, De-esser, Compressor, Limiter and Voice Isolation
    /// sections with an action selected, a switch turned off there an `off`
    /// path, an EQ slot `audio.eq.<slot>` (`AudioPatch.routedInsideAction`,
    /// spec §11 AU-88).
    ///
    /// **The patch goes to the core UNREAD** (deepening D1·5,
    /// `archive/roadmap-7.md` §2.5) — the LAST door of the six, and
    /// the one that used to check the most: `checkActionPatch` walked three
    /// allowed-key sets, `checkVideoEnums` and `checkTextEnums` ran here
    /// alone, and `patchArg`'s round trip decoded the whole thing through
    /// `ActionPatch`. The core walks it group by group now
    /// (`edit_action.rs`'s `check_end_patch` over `patch.rs`), so every
    /// refusal carries the group in its path — `unknown key
    /// "video.filters[1].kindd" in an action end patch` — and three things
    /// that used to LAND do not: a wrong-typed value one level down (a
    /// number where `shadow` belongs read as "clear the shadow"), a
    /// three-element colour (`withOpaqueColors` filled in the alpha), and a
    /// one-key nested object, which REPLACED what the end state held and now
    /// merges into it.
    ///
    /// Two refusals are still made away from `patch.rs` and both are about
    /// this OP: `video.motion` and `text.words` are not animation targets
    /// (`edit_action.rs`), and an empty patch is the core's identity answer
    /// rather than this side's "nothing to change".
    ///
    /// **`schema` is the app's to fill** (spec §11 G-34 (c), G-4). When the
    /// patch names `graphic` and the clip — found in the call's scope, so a
    /// nest's clip is the nest's — is a graphic clip, `graphicEndSchema`
    /// sends the CURRENT revision's schema of the module it is drawn by, read
    /// as `set_graphic` reads it. Otherwise none goes, and the core answers:
    /// `clip N is not a graphic clip` for any other clip (asked before the
    /// schema), and for a value whose module is missing or does not compile,
    /// `graphic.props.<key> needs its module's schema to animate, and none
    /// came with the op` — while a `null` still removes, so a stale key can
    /// leave an end whose module is broken. Nothing here writes a sentence of
    /// its own.
    func setActionEnd(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let action = try actionArg(a, "action", clip)
        let patch = try rawPatchArg(a, "patch")
        // `off` (CI-14) is the caller's own choice; its refusals are the core's.
        let off = try stringsArg(a, "off") ?? []
        let schema = graphicEndSchema(patch, clip, document)
        return try retimingEditResult(
            document, "Action End",
            [
                .setActionEndRaw(
                    clip: clip.id, action: action.id, patch: patch,
                    off: off, schema: schema)
            ])
    }

    /// The schema `set_action_end` sends with a graphic end patch: the
    /// CURRENT revision's, of the module `clip` is drawn by, read through
    /// `compiledModule` as `setGraphic` reads it — or nil when the patch
    /// names no `graphic` (any value, a `null` included), the clip is not a
    /// graphic, or the module is missing or does not compile. It never
    /// throws and reads nothing of the patch beyond the key's presence: what
    /// a missing schema means is the core's sentence to say (D2-1).
    func graphicEndSchema(
        _ patch: Any, _ clip: ClipSnapshot, _ document: ProjectDocument
    ) -> [String: Any]? {
        guard let fields = patch as? [String: Any], fields["graphic"] != nil,
            let name = clip.graphic?.name
        else { return nil }
        return try? compiledModule(named: name, document).schema
    }

    /// `remove_action` — the action lane's trash button, and ⌫ with an
    /// action selected.
    func removeAction(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let action = try actionArg(a, "action", clip)
        return try retimingEditResult(
            document, "Remove Action", [.removeAction(clip: clip.id, action: action.id)])
    }

}

//! `add_speed_ramp`, the speed ramp presets (spec §11 SR-23, #340): a Ramp
//! Up, a Ramp Down, a Speed Dip or a Speed Burst made in ONE step out of
//! ordinary Speed actions — actions whose `end` names a `speed` (SR-1,
//! SR-10) — so undo, the band drags, the inspector and the plan read them
//! exactly as they read one made by hand.
//!
//! **Everything is CLIP time**, as `add_action`'s `at` is: `from` and `to`
//! are both given or both absent, which is the clip's whole length [0, D).
//! The BASE b is the rate the clip plays at `from` before the edit
//! (`rate_in_force`), which after an earlier speed action is that action's
//! end rate and not `clip.speed`.
//!
//! - **Ramp Up / Ramp Down** — one action [from, to) ending at `rate`: the
//!   clip ramps from b to it and holds it after.
//! - **Speed Dip / Speed Burst** — two actions of length r each, r being
//!   `(to − from)·(1 − hold)/2` snapped DOWN onto the grid and never under
//!   one frame: [from, from + r) ending at `rate`, and [to − r, to) ending
//!   at b. The span between them holds the target; at `hold` 0 they abut.
//!
//! "Up" and "down" are about the base rate, not about time: Up and Burst
//! need a rate above b, Down and Dip one below it. A ramp mirrored in TIME
//! would have to change the clip's own `speed`, and a preset makes only
//! Speed actions.
//!
//! **The lane's one rule holds** (spec §5.4): an action the span runs into
//! is a REFUSAL naming it, never replaced — a replacement would drop the
//! action's other keys — and the span tested is the WHOLE of [from, to)
//! for every shape, so an action sitting in a dip's hold gap is refused as
//! well: the gap must hold the target. **The clip keeps its slot** (SR-2):
//! a preset that would read past the media's end is refused naming the
//! largest rate that fits, through R1's solve (`largest_fitting_rate`).
//!
//! Errs come first, then the refusals, each in the order SR-23 lists them;
//! every sentence the lane already has is reused, not restated.

use serde::{Deserialize, Serialize};
use serde_json::{json, Value};

use crate::edit_action::{action_overlaps, action_past_end, overlapping_action};
use crate::edit_action_speed::read_speed_end;
use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
use crate::model::{Action, Clip, Curve, Project};
use crate::outcome::Outcome;
use crate::speed_map::rate_in_force;
use crate::time::Ticks;

/// The four presets (SR-23 (c)).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RampShape {
    RampUp,
    RampDown,
    SpeedDip,
    SpeedBurst,
}

/// A dip's or a burst's hold when `hold` is absent: half the span at the
/// target, a quarter each side ramping.
pub const HOLD_DEFAULT: f64 = 0.5;
/// The most of the span a hold may take. Below 1 so each ramp keeps some
/// length to ease over; one frame is its floor in any case.
pub const HOLD_MAX: f64 = 0.9;

impl RampShape {
    /// The shape as a refusal names it.
    fn name(self) -> &'static str {
        match self {
            RampShape::RampUp => "a ramp up",
            RampShape::RampDown => "a ramp down",
            RampShape::SpeedDip => "a speed dip",
            RampShape::SpeedBurst => "a speed burst",
        }
    }

    /// Whether the target must lie ABOVE the base rate (Up and Burst) or
    /// below it (Down and Dip).
    fn rises(self) -> bool {
        matches!(self, RampShape::RampUp | RampShape::SpeedBurst)
    }

    /// Whether the shape returns to the base rate: two actions and a hold.
    fn returns(self) -> bool {
        matches!(self, RampShape::SpeedDip | RampShape::SpeedBurst)
    }
}

/// One Speed action: a span ending at `rate`.
fn speed_action(id: u32, start: Ticks, duration: Ticks, curve: Curve, rate: f64) -> Action {
    Action {
        id,
        start,
        duration,
        curve,
        end: json!({ "speed": rate }),
    }
}

impl Project {
    /// The speed ramp presets (the module doc, spec §11 SR-23).
    #[allow(clippy::too_many_arguments)]
    pub fn add_speed_ramp(
        &self,
        clip: u32,
        shape: RampShape,
        rate: f64,
        from: Option<Ticks>,
        to: Option<Ticks>,
        curve: Option<Curve>,
        hold: Option<f64>,
    ) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        // Only a media clip has a window to read at a rate; the sentence is
        // the end-rate door's own (`edit_action_speed.rs`).
        read_speed_end(&target, &Value::from(1.0))?;
        if !(rate.is_finite() && rate > 0.0) {
            return Err(format!("rate must be a positive number, not {rate}"));
        }
        let rate = rate.clamp(SPEED_MIN, SPEED_MAX);
        let (from, to) = match (from, to) {
            (None, None) => (0, target.duration),
            (Some(given_from), Some(given_to)) => {
                let from = self.snapped(given_from);
                if from < 0 {
                    return Err(format!("from must not be negative, not {given_from}"));
                }
                (from, self.snapped(given_to))
            }
            _ => return Err("from and to are given together or not at all".to_string()),
        };
        if to <= from {
            return Err(format!("to must be after from, not {to} against {from}"));
        }
        if hold.is_some() && !shape.returns() {
            return Err("hold is for speed_dip and speed_burst only".to_string());
        }

        let length = to - from;
        if to > target.duration {
            return Ok(Outcome::Refused(action_past_end(
                clip,
                from,
                length,
                target.duration,
            )));
        }
        // ONE test over the whole span, whatever the shape (SR-23 (e)).
        if let Some(other) = overlapping_action(&target.actions, None, from, length) {
            return Ok(Outcome::Refused(action_overlaps(clip, other)));
        }
        let frame = self.frame();
        if shape.returns() && length < 2 * frame {
            return Ok(Outcome::Refused(format!(
                "{} needs a span of at least two frames ({} ticks); {from} to {to} ticks is \
                 {length}",
                shape.name(),
                2 * frame
            )));
        }
        let base = rate_in_force(&target, from);
        let wrong_way = if shape.rises() {
            rate <= base
        } else {
            rate >= base
        };
        if wrong_way {
            return Ok(Outcome::Refused(format!(
                "{} needs a rate {} ×{base}, the rate clip {clip} plays at {from} ticks into \
                 it; ×{rate} is not",
                shape.name(),
                if shape.rises() { "above" } else { "below" }
            )));
        }

        let mut next = self.clone();
        let first = next.allocate_id();
        let second = shape.returns().then(|| next.allocate_id());
        let curve = curve.unwrap_or(Curve::EaseInOut);
        // A NaN hold reads as the default; any other is clamped into range.
        let hold = match hold {
            Some(h) if !h.is_nan() => h.clamp(0.0, HOLD_MAX),
            _ => HOLD_DEFAULT,
        };
        let ramp = self
            .snapped_down(((length as f64) * (1.0 - hold) / 2.0) as Ticks)
            .max(frame);
        // The clip with the preset at target rate `x`: the one closure the
        // edit and the fit both build from, so they cannot disagree.
        let build = |x: f64| -> Clip {
            let mut out = target.clone();
            match second {
                None => out
                    .actions
                    .push(speed_action(first, from, length, curve, x)),
                Some(second) => {
                    out.actions.push(speed_action(first, from, ramp, curve, x));
                    out.actions
                        .push(speed_action(second, to - ramp, ramp, curve, base));
                }
            }
            out
        };
        let after = build(rate);
        // A linked clip's rate is refused (spec §11 AU-94).
        if let Some(why) = self.linked_rate_refusal(&target, &after) {
            return Ok(Outcome::Refused(why));
        }
        if let Some(over) = self.overrun(&after) {
            let floor_k = if shape.rises() {
                (base * 1000.0).floor() as i64 + 1
            } else {
                (SPEED_MIN * 1000.0).round() as i64
            };
            let head = format!(
                "{} to ×{rate} would read clip {clip} {over} ticks past the end of its media",
                shape.name()
            );
            return Ok(Outcome::Refused(
                match self.largest_fitting_rate(&build, rate, floor_k) {
                    Some(fit) => format!("{head}; the largest rate that fits is ×{fit}"),
                    None if shape.rises() => format!("{head}, and no rate above ×{base} fits"),
                    None => format!("{head}, and no rate down to ×0.1 fits"),
                },
            ));
        }
        if let Some(slot) = next.clip_mut(clip) {
            *slot = after;
        }
        self.finish(next)
    }
}
//! `set_action_end`'s `speed` arm (format version 27, spec §11 SR-10), and
//! the refusals every action op that can move a ramped clip's out point
//! answers (SR-2, the road map's C).
//!
//! `speed` is a number at the TOP of an action's `end`, beside the groups:
//! the rate the clip ramps to along the action's curve and holds after
//! (`speed_map.rs`). It is a door of its own, as `graphic` is
//! (`edit_action_graphic.rs`): not a property group, so `check_end_patch`
//! steps over it and this file reads it. A finite number is clamped to
//! ×0.1–×1000 as `set_speed` clamps; any other kind is an `Err`, and so is a
//! rate on a clip that is not a media clip, which has no window to read at
//! one; a `null` removes it, as it removes any key.
//!
//! **The clip keeps its slot** (SR-2): a ramp edit never moves `start` or
//! `duration`, it changes how much source the clip reads, `in + S(D)`. An
//! edit that would read past the media's end is REFUSED, naming what fits:
//! the largest end rate (R1) — S(D) is affine in one action's end rate, so
//! two readings solve it — or, when no rate down to ×0.1 fits, the latest
//! clip end at ×0.1 (R2); and for a retime, a removal or an end rate taken
//! away, the latest clip end (R3).

use serde_json::Value;

use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
use crate::export::describe;
use crate::model::{Clip, Project, Source};
use crate::speed_map::SpeedMap;
use crate::time::Ticks;

/// Reads a patch's `speed` for `clip`: `None` for a `null` (remove it), the
/// clamped rate for a number. `Err` for any other JSON kind, then for a
/// clip that is not a media clip.
pub(crate) fn read_speed_end(clip: &Clip, value: &Value) -> Result<Option<f64>, String> {
    if value.is_null() {
        return Ok(None);
    }
    let Some(rate) = value.as_f64() else {
        return Err(format!("speed must be a number, not {}", describe(value)));
    };
    if !matches!(clip.source, Source::Media { .. }) {
        return Err(format!(
            "clip {} is not a media clip, and only a media clip's action can end at a speed",
            clip.id
        ));
    }
    Ok(Some(rate.clamp(SPEED_MIN, SPEED_MAX)))
}

/// `clip` with action `action`'s end rate set to `rate`.
fn ending_at(clip: &Clip, action: u32, rate: f64) -> Clip {
    let mut out = clip.clone();
    if let Some(found) = out.actions.iter_mut().find(|a| a.id == action) {
        if let Value::Object(end) = &mut found.end {
            end.insert("speed".to_string(), Value::from(rate));
        }
    }
    out
}

/// The `{}` a refusal names a rate in, on the 0.001 grid it was found on.
fn thousandths(k: i64) -> f64 {
    k as f64 / 1000.0
}

impl Project {
    /// The latest clip END that fits: the clip's start plus S⁻¹ of what the
    /// file holds past `in`, snapped DOWN onto the grid, never before the
    /// start.
    fn latest_fitting_end(&self, clip: &Clip) -> Ticks {
        let Some((source_in, file)) = self.window_of(clip) else {
            return clip.start;
        };
        let remaining = file.saturating_sub(source_in).max(0) as f64;
        let fits = match SpeedMap::of(clip) {
            Some(map) => map.time_at(remaining),
            None if clip.speed.is_finite() && clip.speed > 0.0 => {
                let t = (remaining / clip.speed).floor();
                if t.is_finite() {
                    t as Ticks
                } else {
                    0
                }
            }
            None => remaining as Ticks,
        };
        self.snapped_down(clip.start.saturating_add(fits))
            .max(clip.start)
    }

    /// The largest end rate on the 0.001 grid, below `rate`, at which
    /// action `action` of `after` reads inside its file: R1's solve, then
    /// its step down. `None` when none down to ×0.1 does. Read by R1 and by
    /// a split's second half (spec §11 SR-18 (e)).
    pub(crate) fn largest_fitting_end_rate(
        &self,
        after: &Clip,
        action: u32,
        rate: f64,
    ) -> Option<f64> {
        let floor = (SPEED_MIN * 1000.0).round() as i64;
        self.largest_fitting_rate(&|x| ending_at(after, action, x), rate, floor)
    }

    /// The largest rate x on the 0.001 grid, below `rate` and at or above
    /// `floor_k` thousandths, at which the clip `at_rate(x)` reads inside
    /// its file: R1's solve, then its step down. `None` when none does.
    /// `at_rate` must make S(D) affine in x — one action's end rate
    /// (`largest_fitting_end_rate`), or a preset's target, which every
    /// piece it builds ramps to, holds or ramps from (`add_speed_ramp`,
    /// spec §11 SR-23 (g)).
    pub(crate) fn largest_fitting_rate(
        &self,
        at_rate: &dyn Fn(f64) -> Clip,
        rate: f64,
        floor_k: i64,
    ) -> Option<f64> {
        let probe = at_rate(rate);
        let (source_in, file) = self.window_of(&probe)?;
        let fits = |x: f64| self.overrun(&at_rate(x)).is_none();
        // S(D) = α + β·x in the rate x: read at two rates in range, solved
        // for the file's remainder.
        let read = |x: f64| SpeedMap::of(&at_rate(x)).map(|m| m.source_at(probe.duration));
        let solved = match (read(SPEED_MIN), read(1.0)) {
            (Some(low), Some(one)) => {
                let beta = (one - low) / (1.0 - SPEED_MIN);
                let alpha = low - SPEED_MIN * beta;
                let remaining = file.saturating_sub(source_in) as f64;
                (beta > 0.0).then(|| (remaining - alpha) / beta)
            }
            _ => None,
        };
        let x = solved.filter(|x| x.is_finite())?;
        // Floored to 0.001, never at or above the rate that overran, then
        // stepped down a thousandth until it fits. The millionth keeps a
        // solve that lands a hair under an exact thousandth (×4 read as
        // 3.9999999) on it; the step down catches the rest.
        let below = (rate * 1000.0).ceil() as i64 - 1;
        let mut k = ((x * 1000.0 + 1e-6).floor() as i64).min(below).max(floor_k);
        while k >= floor_k {
            if fits(thousandths(k)) {
                return Some(thousandths(k));
            }
            k -= 1;
        }
        None
    }

    /// R1 / R2: `after` is the clip with action `action` ending at `rate`
    /// (already clamped). `None` when it fits.
    pub(crate) fn end_rate_refusal(&self, after: &Clip, action: u32, rate: f64) -> Option<String> {
        let over = self.overrun(after)?;
        let clip = after.id;
        if let Some(fitting) = self.largest_fitting_end_rate(after, action, rate) {
            return Some(format!(
                "ending action {action} at ×{rate} would read clip {clip} {over} ticks past the \
                 end of its media; the largest end rate that fits is ×{fitting}"
            ));
        }
        let end = self.latest_fitting_end(&ending_at(after, action, SPEED_MIN));
        Some(format!(
            "ending action {action} at ×{rate} would read clip {clip} {over} ticks past the end \
             of its media, and no end rate down to ×0.1 fits; at ×0.1 the latest clip end that \
             fits is {end} ticks"
        ))
    }

    /// R3: `after` is the clip once `what` (`retiming action 7`, `removing
    /// action 7`, `removing action 7's end rate`) is done. `None` when it
    /// fits.
    pub(crate) fn overrun_refusal(&self, after: &Clip, what: &str) -> Option<String> {
        let over = self.overrun(after)?;
        let end = self.latest_fitting_end(after);
        Some(format!(
            "{what} would read clip {} {over} ticks past the end of its media; the latest clip \
             end that fits is {end} ticks",
            after.id
        ))
    }
}
