    pub fn add_speed_ramp(
        &self,
        clip: u32,
        shape: RampShape,
        rate: f64,
        from: Option<Ticks>,
        to: Option<Ticks>,
        curve: Option<Curve>,
        hold: Option<f64>,
    ) -> Result<Outcome, String> {
